    Frame firstPeer,changedPeer,recoveredPeer;ok &=peer.render(peerScene.root,firstPeer,"ordinary offscreen peer B")&&color(firstPeer,ordinaryColor(),"ordinary peer independent normal lighting/base");ok &=retainedWindow("peer rendered");
    peerScene.setDiffuse({{.6,.25,.7}});peerScene.setBase({{40,220,90,255}});ok &=peer.render(peerScene.root,changedPeer,"ordinary peer B mutation")&&color(changedPeer,ordinaryColor(),"ordinary peer mutated material/base");ok &=retainedWindow("peer mutated");
    const auto originalUv=peerScene.baseUv->point[0];peerScene.baseUv->point.set1Value(0,SbVec2f(std::numeric_limits<float>::quiet_NaN(),originalUv[1]));ok &=peer.reject(peerScene.root,changedPeer,"ordinary peer nonfinite source UV");ok &=retainedWindow("peer invalid submission refused");
