 for(unsigned size:{97u,160u,144u}){width=height=size;XResizeWindow(d,window,width,height);XSync(d,False);ok &=check(target->resize(SbVec2i32(width,height)),"window resize admitted");action.setViewportRegion(SbViewportRegion(width,height));ok &=draw(back,backShown,"resized current pixels");}
